package vn.covie.needs.api;

import jakarta.validation.Valid;import java.net.URI;import java.util.UUID;import org.springframework.http.HttpHeaders;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;import vn.covie.needs.api.dto.*;import vn.covie.needs.application.NeedResponseService;import vn.covie.needs.application.NeedResponseRateLimit;
@RestController @RequestMapping("/api/v1/need-requests/{needRequestId}/responses") public class NeedResponseController {private final NeedResponseService responses;private final NeedResponseRateLimit rateLimit;public NeedResponseController(NeedResponseService responses,NeedResponseRateLimit rateLimit){this.responses=responses;this.rateLimit=rateLimit;}
@PostMapping @ResponseStatus(org.springframework.http.HttpStatus.CREATED) public ResponseEntity<NeedResponseResponse> create(@PathVariable UUID needRequestId,@RequestHeader(value="Idempotency-Key",required=false)String key,@Valid@RequestBody CreateNeedResponseRequest request){rateLimit.forLocation(request.merchantLocationId());var execution=responses.create(needRequestId,key,request);NeedResponseResponse body=execution.response();return ResponseEntity.created(URI.create("/api/v1/need-requests/"+needRequestId+"/responses/"+body.id())).eTag("\"v"+body.version()+"\"").body(body);}
@PutMapping("/{responseId}")public ResponseEntity<NeedResponseResponse> replace(@PathVariable UUID needRequestId,@PathVariable UUID responseId,@RequestHeader(value=HttpHeaders.IF_MATCH,required=false)String ifMatch,@Valid@RequestBody ReplaceNeedResponseRequest request){rateLimit.forResponse(needRequestId,responseId);NeedResponseResponse body=responses.replace(needRequestId,responseId,ifMatch,request);return ResponseEntity.ok().eTag("\"v"+body.version()+"\"").body(body);}
@PostMapping("/{responseId}/withdraw")public ResponseEntity<NeedResponseResponse> withdraw(@PathVariable UUID needRequestId,@PathVariable UUID responseId,@RequestHeader(value="Idempotency-Key",required=false)String key){rateLimit.forResponse(needRequestId,responseId);NeedResponseResponse body=responses.withdraw(needRequestId,responseId,key).response();return ResponseEntity.ok().eTag("\"v"+body.version()+"\"").body(body);}}
